def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: defect is strictly dominant when no future consequence remains.
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    total_c = 0
    for a in op:
        if a == 'C':
            total_c += 1

    w10 = op[-10:] if n >= 10 else op
    w10_me = me[-10:] if n >= 10 else me
    len10 = len(w10)

    recent10_c = 0
    for a in w10:
        if a == 'C':
            recent10_c += 1

    recent10_me_c = 0
    for a in w10_me:
        if a == 'C':
            recent10_me_c += 1

    w20 = op[-20:] if n >= 20 else op
    len20 = len(w20)

    recent20_c = 0
    for a in w20:
        if a == 'C':
            recent20_c += 1

    runD = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            runD += 1
        else:
            break

    runMDD = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and op[i] == 'D':
            runMDD += 1
        else:
            break

    # Evidence about whether this opponent tolerates unilateral defection.
    # punished: after our D and their C, they answered with D next round.
    # forgiven: after our D and their C, they answered with C next round.
    pun = 0
    forg = 0
    rp = 0
    rf = 0
    start_recent = n - 20 if n > 20 else 0

    for i in range(1, n):
        if me[i - 1] == 'D' and op[i - 1] == 'C':
            if op[i] == 'D':
                pun += 1
                if i >= start_recent:
                    rp += 1
            elif op[i] == 'C':
                forg += 1
                if i >= start_recent:
                    rf += 1

    # Treat persistent hostility as a reason to defend rather than keep trying to reset.
    hostile = False
    if runD >= 5 and recent20_c <= 4:
        hostile = True
    elif n >= 10 and recent10_c <= 2:
        hostile = True
    elif n >= 12 and total_c * 10 < n * 3:
        hostile = True

    if hostile:
        return 'D'

    # Learned generous: repeatedly tolerated our exploitation without confirmed punishment.
    # Against such opponents, continue exploiting whenever they are still cooperating.
    if pun == 0 and forg >= 2 and rf == 0:
        if op[-1] == 'C':
            return 'D'
        return 'C' if total_c * 2 > n else 'D'

    # After one confirmed tolerated exploit, test again carefully.
    if pun == 0 and forg == 1 and rf == 0:
        if op[-1] == 'C' and me[-1] == 'C':
            if rng.random() < 0.3:
                return 'D'

    # Rare discovery probes when the recent history is completely clean and very cooperative.
    if pun == 0 and forg == 0 and n >= 4:
        clean = recent10_c == len10 and recent10_me_c == len10
        friendly_now = op[-1] == 'C' and me[-1] == 'C'
        if clean and friendly_now and total_c * 4 >= n * 3:
            if rng.random() < 0.02:
                return 'D'

    last_opp = op[-1]
    last_me = me[-1]

    if last_opp == 'D':
        # If this is punishment for our recent exploit, appease to restore mutual cooperation.
        if n >= 2 and me[-2] == 'D' and op[-2] == 'C' and last_me == 'C':
            return 'C'

        # Mutual defection: break the cycle if the opponent has been sufficiently friendly.
        if last_me == 'D':
            if runMDD <= 3 and (total_c * 2 > n or recent10_c * 5 >= len10 * 3):
                return 'C'
            return 'D'

        # Opponent defected while we cooperated: retaliate once.
        return 'D'

    # Opponent cooperated.
    # If we just punished or probed, return to cooperation unless exploitation is established.
    if last_me == 'D':
        return 'C'

    return 'C'
